SELECT cli.id_persona AS "IdPersona", per.id_direccion_electronica_principal AS "IdDireccionElectronicaPrincipal", per.nombre_completo AS "NombreCompleto", dtos.razon_social AS "corredora", cli.id_empresa AS "IdEmpresa", usu.id_usuario AS "IdUsuario", usu.tipo_entidad AS "TipoEntidad" FROM t_pla_acc_usuario usu LEFT JOIN t_socneg_soc_socio_de_negocio cli ON (usu.tipo_entidad = 'CLI' AND usu.id_entidad = cli.id_cliente) OR (usu.tipo_entidad = 'EMP' AND usu.id_entidad = cli.id_empleado) OR (usu.tipo_entidad = 'PER' AND usu.id_entidad = cli.id_persona) LEFT JOIN v_socneg_per_consultar_persona per ON per.id_persona = cli.id_persona LEFT JOIN v_pla_ctt_consultar_contrato_datos_generales dtos ON dtos.id_empresa = cli.id_empresa WHERE usu.codigo_usuario = :CodigoUsuario LIMIT 1